import { test, expect } from '@playwright/test';

test.describe('Graceful Recovery After JavaScript Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should recover gracefully after a JavaScript error and display error boundary', async ({ page }) => {
    // Intercept the API call that will fail
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Click the button that triggers the error
    const errorButton = page.getByRole('button', { name: /load data/i });
    await errorButton.click();

    // Wait for the error boundary to render
    await page.waitForTimeout(500);

    // Verify the error boundary is visible
    const errorBoundary = page.getByText(/error boundary/i);
    await expect(errorBoundary).toBeVisible();

    // Verify the error message is displayed
    const errorMessage = page.getByText(/failed to load data/i);
    await expect(errorMessage).toBeVisible();

    // Verify the retry button is available
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify the main content is not visible
    const mainContent = page.getByText(/dashboard/i);
    await expect(mainContent).not.toBeVisible();

    // Click retry button
    await retryButton.click();

    // Verify the error boundary is gone
    await expect(errorBoundary).not.toBeVisible();

    // Verify the main content is visible after retry
    await expect(mainContent).toBeVisible();
  });

  test('should handle multiple consecutive JavaScript errors and maintain app state', async ({ page }) => {
    // Intercept the API call and abort it
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Click the button to trigger the first error
    const errorButton = page.getByRole('button', { name: /load data/i });
    await errorButton.click();

    // Wait for the first error boundary to appear
    await page.waitForTimeout(500);
    const errorBoundary = page.getByText(/error boundary/i);
    await expect(errorBoundary).toBeVisible();

    // Click retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await retryButton.click();

    // Verify the error boundary is gone
    await expect(errorBoundary).not.toBeVisible();

    // Click the button again to trigger a second error
    await errorButton.click();

    // Wait for the second error boundary to appear
    await page.waitForTimeout(500);
    await expect(errorBoundary).toBeVisible();

    // Verify the retry button is still available
    await expect(retryButton).toBeVisible();

    // Verify the app state is preserved (e.g., user profile is still visible)
    const userProfile = page.getByText(/user profile/i);
    await expect(userProfile).toBeVisible();

    // Verify the retry button is still functional
    await retryButton.click();
    await expect(errorBoundary).not.toBeVisible();
  });
});
